"https://github.com/jyqj\",\"followers_url\":\"https://api.github.com/users/jyqj/followers\",\"following_url\":\"https://api.github.com/users/jyqj/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/jyqj/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/jyqj/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/jyqj/subscriptions\",\"organizations_url\":\"https://api.github.com/users/jyqj/orgs\",\"repos_url\":\"https://api.github.com/users/jyqj/repos\",\"events_url\":\"https://api.github.com/users/jyqj/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/jyqj/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"parents\":[{\"sha\":\"4786c1457b47c5baf4c09d32b96048795e863111\",\"url\":\"https://api.github.com/repos/jyqj/codecortex/commits/4786c1457b47c5baf4c09d32b96048795e863111\",\"html_url\":\"https://github.com/jyqj/codecortex/commit/4786c1457b47c5baf4c09d32b96048795e863111\"}]}],\"files\":[{\"sha\":\"d11f83361707dae7f7a218c1522579d1b9c374c6\",\"filename\":\".github/workflows/p8-scale-100k-diagnostic.yml\",\"status\":\"added\",\"additions\":415,\"deletions\":0,\"changes\":415,\"blob_url\":\"https://github.com/jyqj/codecortex/blob/5ce1ed4306ddf1a791f12da45d5892383e453d65/.github%2Fworkflows%2Fp8-scale-100k-diagnostic.yml\",\"raw_url\":\"https://github.com/jyqj/codecortex/raw/5ce1ed4306ddf1a791f12da45d5892383e453d65/.github%2Fworkflows%2Fp8-scale-100k-diagnostic.yml\",\"contents_url\":\"https://api.github.com/repos/jyqj/codecortex/contents/.github%2Fworkflows%2Fp8-scale-100k-diagnostic.yml?ref=5ce1ed4306ddf1a791f12da45d5892383e453d65\",\"patch\":\"@@ -0,0 +1,415 @@\\n+name: P8 independent 100k diagnostic with retained progress\\n+\\n+on:\\n+  workflow_dispatch:\\n+  pull_request:\\n+    types: [labeled]\\n+\\n+permissions:\\n+  contents: read\\n+\\n+env:\\n+  CARGO_TERM_COLOR: never\\n+  CARGO_INCREMENTAL: \\\"0\\\"\\n+  CARGO_BUILD_JOBS: \\\"2\\\"\\n+  RUSTFLAGS: \\\"\\\"\\n+\\n+jobs:\\n+  build:\\n+    if: github.event_name == 'workflow_dispatch' || github.event.label.name == 'p8-scale-100k-diagnostic-run'\\n+    runs-on: ubuntu-24.04\\n+    timeout-minutes: 45\\n+    steps:\\n+      - uses: actions/checkout@v4\\n+        with:\\n+          ref: ${{ github.event.pull_request.head.sha || github.sha }}\\n+          sparse-checkout-cone-mode: false\\n+          sparse-checkout: |\\n+            /*\\n+            !/artifacts/\\n+            /artifacts/checkpoints/capability-snapshot-optimization-20261003/current-status-under-test.rs\\n+            /artifacts/checkpoints/capability-snapshot-optimization-20261003/v2-status-checks.rs\\n+      - uses: dtolnay/rust-toolchain@stable\\n+        with:\\n+          toolchain: 1.95.0\\n+          components: rustfmt\\n+      - name: Original formatting and scale protocol controls\\n+        env:\\n+          CARGO_TARGET_DIR: ${{ runner.temp }}/p8-diagnostic-protocol-cargo\\n+        run: |\\n+          cargo fmt --all -- --check\\n+          cargo test --locked -p cc-eval --test p8_scale\\n+          PYTHONDONTWRITEBYTECODE=1 python3 -m unittest discover -s scripts/tests -p test_p8_scale_diagnostic_capture.py -v\\n+      - name: Compile one immutable executable with the original driver\\n+        run: |\\n+          python3 scripts/p8_scale_matrix.py build --root \\\"$GITHUB_WORKSPACE\\\" \\\\\\n+            --output \\\"$RUNNER_TEMP/p8-diagnostic-build\\\" --target-directory \\\"$RUNNER_TEMP/p8-diagnostic-cargo\\\"\\n+      - uses: actions/upload-artifact@v4\\n+        if: always()\\n+        with:\\n+          name: p8-100k-diagnostic-build-${{ github.run_id }}-${{ github.run_attempt }}\\n+          path: ${{ runner.temp }}/p8-diagnostic-build\\n+          if-no-files-found: error\\n+\\n+  diagnose:\\n+    needs: build\\n+    runs-on: ubuntu-24.04\\n+    timeout-minutes: 350\\n+    env:\\n+      DIAGNOSTIC_DIR: ${{ runner.temp }}/p8-100k-diagnostic\\n+    steps:\\n+      - uses: actions/checkout@v4\\n+        with:\\n+          ref: ${{ github.event.pull_request.head.sha || github.sha }}\\n+          sparse-checkout-cone-mode: false\\n+          sparse-checkout: |\\n+            /*\\n+            !/artifacts/\\n+      - uses: dtolnay/rust-toolchain@stable\\n+        with:\\n+          toolchain: 1.95.0\\n+      - uses: actions/download-artifact@v4\\n+        with:\\n+          name: p8-100k-diagnostic-build-${{ github.run_id }}-${{ github.run_attempt }}\\n+          path: ${{ runner.temp }}/p8-diagnostic-build\\n+      - name: Original capacity preparation\\n+        env:\\n+          P8_EXPECTED_SOURCE: ${{ github.event.pull_request.head.sha || github.sha }}\\n+          P8_CAPACITY_PREPARE_ALLOWED: ${{ github.repository == 'jyqj/codecortex' && runner.environment == 'github-hosted' && runner.os == 'Linux' }}\\n+        run: |\\n+          python3 scripts/p8_runner_capacity.py --scale 100000 \\\\\\n+            --output \\\"$RUNNER_TEMP/p8-diagnostic-capacity\\\" --prepare-ephemeral\\n+      - uses: actions/upload-artifact@v4\\n+        if: always()\\n+        with:\\n+          name: p8-100k-diagnostic-capacity-${{ github.run_id }}-${{ github.run_attempt }}\\n+          path: ${{ runner.temp }}/p8-diagnostic-capacity\\n+          if-no-files-found: error\\n+      - name: Launch the original full-stage 100k rep0 command\\n+        id: launch\\n+        env:\\n+          EXPECTED_SOURCE: ${{ github.event.pull_request.head.sha || github.sha }}\\n+        run: |\\n+          chmod +x \\\"$RUNNER_TEMP/p8-diagnostic-build/p8-scale\\\"\\n+          python3 scripts/p8_scale_diagnostic_capture.py launch --directory \\\"$DIAGNOSTIC_DIR\\\" \\\\\\n+            --root \\\"$GITHUB_WORKSPACE\\\" --build \\\"$RUNNER_TEMP/p8-diagnostic-build\\\" --expected-source \\\"$EXPECTED_SOURCE\\\"\\n+      - name: Freeze original byte prefix at interval 1 of 20\\n+        id: checkpoint_00\\n+        if: always() && steps.launch.outcome == 'success'\\n+      